-- Import the original Haramain Collection catalogue once.
-- Safe to re-run: nothing is inserted when the products table already has rows.

insert into public.products
  (name, category, price, old_price, description, details, image_url, alt_text, badge, featured, quantity, active)
select * from (values
  ('Noor Gold Electric Oud Daan', 'Oud Daan', 1499, 1799, 'An elegant electric oud and bakhoor burner with a rich gold finish. Designed for convenient, charcoal-free fragrance at home.', array['Electric heating','Decorative metallic finish','Suitable for oud chips and bakhoor','Easy on/off switch'], 'WhatsApp Image 2026-09-27 at 3.27.28 PM.jpeg', 'Gold electric oud daan incense burner with decorative palm motif', 'Bestseller', true, 10, true),
  ('Sultan Lantern Bakhoor Burner', 'Oud Daan', 1899, 2199, 'A statement lantern-style burner that fills your space with fragrance and a warm decorative glow.', array['Electric heating','Warm ambient light','Premium gold-tone detailing','For home and gifting'], 'WhatsApp Image 2026-09-27 at 3.27.53 PM.jpeg', 'Lantern style electric bakhoor burner glowing on a dark background', 'New', true, 10, true),
  ('Mughal Crown Oud Burner', 'Oud Daan', 1699, 1999, 'A tall, regal oud burner inspired by traditional Mughal ornamentation, made to elevate festive and everyday spaces.', array['Tall decorative profile','Electric operation','Antique gold finish','Ideal wedding gift'], 'WhatsApp Image 2026-09-27 at 3.27.51 PM.jpeg', 'Tall gold electric oud burner with ornate feather design', 'Popular', true, 10, true),
  ('Crystal Noor Electric Burner', 'Oud Daan', 1599, null, 'A refined silver-finish burner with floral lattice work and a crystal centre for a graceful premium look.', array['Silver-tone finish','Crystal accent','Electric heating','Suitable for bakhoor'], 'WhatsApp Image 2026-09-27 at 3.27.54 PM.jpeg', 'Silver electric incense burner with crystal detail and floral lattice', 'Limited', true, 10, true),
  ('Palm Heritage Oud Daan Set', 'Oud Daan', 1199, 1399, 'A compact heritage-inspired electric burner available in contrasting metallic finishes.', array['Compact tabletop size','Electric heating','Palm motif','Colour subject to availability'], 'WhatsApp Image 2026-09-27 at 3.27.56 PM.jpeg', 'Pair of black and silver palm motif electric oud burners', 'Value Pick', false, 10, true),
  ('Royal Geometric Bakhoor Burner', 'Oud Daan', 1799, null, 'A dramatic geometric burner that combines traditional fragrance rituals with convenient electric heating.', array['Geometric lattice','Electric operation','Rich gold finish','Statement decor piece'], 'WhatsApp Image 2026-09-27 at 3.27.57 PM.jpeg', 'Gold geometric electric bakhoor burner with glowing lattice pattern', 'Premium', false, 10, true),
  ('Ayat Calligraphy Sculpture', 'Islamic Décor', 899, null, 'A sculptural tabletop accent with calligraphy-inspired detailing for prayer rooms, shelves and thoughtful gifting.', array['Tabletop decor','Cream and gold finish','Calligraphy-inspired design','Gift-ready style'], 'WhatsApp Image 2026-09-27 at 3.28.00 PM.jpeg', 'Cream and gold Islamic calligraphy tabletop sculpture', 'Gift Pick', false, 10, true),
  ('Embroidered Islamic Wall Hanging', 'Islamic Décor', 749, null, 'A richly coloured, traditional wall hanging with floral embroidery and Islamic calligraphy.', array['Decorative embroidery','Ready to hang','Traditional floral border','Suitable for home or gifting'], 'WhatsApp Image 2026-09-27 at 3.29.12 PM.jpeg', 'Traditional embroidered Islamic calligraphy wall hanging with floral border', 'Handcrafted Look', false, 10, true),
  ('Maroon Velvet Quran Gift Box', 'Quran & Gifts', 2499, null, 'A premium Quran presentation box planned in our signature palette. Replace the placeholder when the real photo is ready.', array['Premium gift presentation','Velvet-look finish','Ideal for weddings and special occasions','Final design may vary'], 'images/placeholder-quran.svg', 'Maroon and gold placeholder illustration for a Quran gift box', 'Coming Soon', false, 10, true),
  ('Complete Hajj & Umrah Kit', 'Hajj & Umrah', 3499, null, 'A convenient all-in-one travel kit planned for Hajj and Umrah pilgrims. Confirm current contents on WhatsApp before ordering.', array['Travel-ready essentials','Organised carry format','Suitable for gifting','Contents confirmed on WhatsApp'], 'images/placeholder-hajj-kit.svg', 'Cream and maroon placeholder illustration for a complete Hajj and Umrah kit', 'Essential', true, 10, true),
  ('Royal Musk Attar', 'Attar & Perfume', 599, 699, 'A warm, refined attar concept with musky depth, designed for everyday wear and gifting.', array['Concentrated perfume oil','Alcohol-free concept','Long-wearing fragrance','Compact gifting size'], 'images/placeholder-attar.svg', 'Gold attar perfume bottle placeholder on a maroon background', 'Alcohol Free', true, 10, true),
  ('Zamzam Travel Bottle Set', 'Zamzam Bottles', 299, null, 'Empty bottles prepared for secure Zamzam water packing and distribution after your journey.', array['Empty bottle set','Travel-friendly design','Secure cap','Available in multiple quantities'], 'images/placeholder-zamzam.svg', 'Cream and gold placeholder illustration for empty Zamzam bottles', 'Travel Ready', false, 10, true)
) as seed(name, category, price, old_price, description, details, image_url, alt_text, badge, featured, quantity, active)
where not exists (select 1 from public.products);
